 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        scwin.hideDebugCtrls();
        await scwin.setHeader();
        await scwin.initPage();

        // opener에서 받아온 데이터 세팅
        // 채권담당자조회 화면에서 이 화면을 팝업함. 2022-07-26 by KHJ
        scwin.setDataFromOpener();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30308.onpageload" });
    }
};

