/**
 * @method
 * @name cmb_Reserve_onselchange
 * @description cmb_Reserve onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_Reserve_onselchange = function() {
    try {
        if (cmb_Reserve.getValue() === "Y") {
            panel_reserve.show("");
            cmb_EMAIL.setValue("N");
            cmb_EMAIL.setDisabled(true);
        } else {
            panel_reserve.hide();
            if (txb_msg_gbn.getValue() === '2') {
                cmb_EMAIL.setDisabled(true);
            } else {
                cmb_EMAIL.setDisabled(false);
            }

            // 예약 전송 날짜 초기값
            const ToDay = $c.ut.cGetToday2();
            edt_Reserve_Date.setValue(ToDay);

            // 예약 전송 시간 초기값
            cmb_Reserve_hh.setValue("99");
            cmb_Reserve_mm.setValue("99");
            // initPage();

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30308.cmb_Reserve_onselchange" });
    }
};

