///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    txb_EMP_NO.setValue(scwin.gEmpNo);
    txb_dep_cd.setValue(scwin.gDepCd);
    txb_fromName.setValue(js_emp_nm);
    txb_fromEmail.setValue(js_email);
    cmb_EMAIL.setValue("N");
    cmb_Reserve.setValue("N");
    txb_msg_gbn.setValue($c.stf.getQuery(frame.srcUrl, "MSG_GBN"));
};

/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPage = async function() {
    scwin.gNOTI_SVC_ID = $c.stf.getQuery(frame.srcUrl, "NOTI_SVC_ID");
    scwin.gAddInput = $c.stf.getQuery(frame.srcUrl, "ADD_INPUT");
    if (scwin.gAddInput === 'Y') {
        await scwin.read();
        scwin.setCode();
    } else {
        await scwin.setHeader();
        scwin.setCode();
    }
    fn_ReadBasicInfo();
    if (txb_msg_gbn.getValue() === '2') {
        // (유)주식시장운영팀, 코스닥시장운영팀, 코넥스시장운영팀
        if (scwin.gDepCd === "2220" || scwin.gDepCd === "3220" || scwin.gDepCd === "3B10") {
            if (scwin.gDepCd === "2220") {
                txa_title.setValue("자사주호가 미제출하신분은 장종료 30분전까지 제출바랍니다. 유가 운영팀");
            } else if (scwin.gDepCd === "3220") {
                scwin.marketNm = "KOSDAQ";
                txa_title.setValue("자사주 호가제출 마감 10분 전입니다.\n" + "- " + scwin.marketNm + " 시장운영팀 -");
            } else if (scwin.gDepCd === "3B10") {
                scwin.marketNm = "KONEX";
                txa_title.setValue("자사주 호가제출 마감 20분 전입니다.\n" + "- " + scwin.marketNm + " 시장운영팀 -");
            }
        }
        $c.cm.setColumnProp(grd_Receiver, "COM_ABBRV", "Show", false);
        $c.cm.setColumnProp(grd_Receiver, "EMAIL", "name", '신청일자');
        $c.cm.setColumnProp(grd_Receiver, "EMAIL", "mask", 'XXXX-XX-XX');
        $c.cm.setColumnProp(grd_Receiver, "CHRG_NM", "width", '200');
        $c.cm.setColumnProp(grd_Receiver, "CELLPHONE_NO", "width", '260');
        cmb_EMAIL.setDisabled(true);
    }
};

/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    panel_debug.hide();
    txb_msg_gbn.hide();
};

/**
 * @method
 * @name registerSMS
 * @description register SMS 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerSMS = async function() {
    if (await scwin.checkForm()) {
        let msg = $c.stf.getMessageParam("MSG-A006", "전송");
        const res = window.confirm(msg);
        if (res) {
            dts_Master.setCellData(1, "EMAIL_YN", cmb_EMAIL.getValue());
            dts_Master.setCellData(1, "RESERVE_YN", cmb_Reserve.getValue());
            dts_Master.setCellData(1, "RESERVE_DATE", edt_Reserve_Date.getValue());
            dts_Master.setCellData(1, "RESERVE_HH", cmb_Reserve_hh.getValue());
            dts_Master.setCellData(1, "RESERVE_MM", cmb_Reserve_mm.getValue());
            const url = "/SmsMgt.do?method=registerSMS" + "&SCREN_ID=" + "ULDSTF30308.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Master, I:pInputDetail=dts_Receiver)";
            trs_Save.post();
        }
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    let msg = "";
    if (txa_title.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "보내는 내용");
        await $c.win.alert(msg);
        txa_title.Focus();
        return false;
    }

    // setObjectValue(txb_title_size, getStringSize(getObjectValue(txa_title)));

    if ($c.stf.getStringSize(txa_title.getValue()) > 80) {
        await $c.win.alert('보내는내용이 80Byte가 초과되었습니다.');
        txa_title.Focus();
        return false;
    }
    if (txb_snd_no.getValue() === "" || txb_snd_no.getValue() === "-") {
        msg = $c.stf.getMessageParam("MSG-A005", "보내는 번호");
        await $c.win.alert(msg);
        txb_snd_no.focus();
        return false;
    }
    if (!$c.stockSearch.isNumber(txb_snd_no.getValue())) {
        await $c.win.alert("[보내는 번호]를 숫자로 입력해주세요.");
        // txb_snd_no.value = "";
        txb_snd_no.focus();
        return;
    }
    if ($c.stf.getStringSize(txb_snd_no.getValue()) > 11) {
        await $c.win.alert('보내는 번호가 11Byte가 초과되었습니다.');
        txb_snd_no.focus();
        return false;
    }
    if (txb_EMP_NO.getValue() === "") {
        await $c.win.alert("세션정보를 받지 못했습니다.");
        txb_EMP_NO.focus();
        return false;
    }

    // dts_Receiver 에서 CHECK 된 걸 찾는다.
    let total = 0;
    for (let i = 0; i < dts_Receiver.getRowCount(); i++) {
        const chk = dts_Receiver.getCellData(i, "CHECK");
        if (chk === "T" || chk === "1") {
            total++;
        }
    }
    if (total === 0) {
        await $c.win.alert("선택된 수신자가 없습니다.");
        return false;
    }

    // 예약전송 체크
    if (cmb_Reserve.getValue() === 'Y') {
        if (cmb_Reserve_hh.getValue() === "" || cmb_Reserve_hh.getValue() === "99") {
            await $c.win.alert("예약 전송일자의 시를 선택하세요.");
            cmb_Reserve_hh.focus();
            return false;
        }
        if (cmb_Reserve_mm.getValue() === "" || cmb_Reserve_mm.getValue() === "99") {
            await $c.win.alert("예약 전송일자의 분을 선택하세요.");
            cmb_Reserve_mm.focus();
            return false;
        }
        const dNow = new Date();

        // 현재 날짜,시간
        const pYear = dNow.getYear();
        let pMonth = dNow.getMonth() + 1;
        let pDay = dNow.getDate();
        const pHour = dNow.getHours();
        const pMinute = dNow.getMinutes();
        if (pMonth <= 9) {
            pMonth = "0" + pMonth;
        }
        if (pDay <= 9) {
            pDay = "0" + pDay;
        }
        const pDate = pYear + "" + pMonth + "" + pDay;

        // 예약전송  날짜,시간
        const rYear = edt_Reserve_Date.getValue().substring(0, 4);
        const rMonth = edt_Reserve_Date.getValue().substring(4, 6);
        const rDay = edt_Reserve_Date.getValue().substring(6, 8);
        const rHour = cmb_Reserve_hh.getValue();
        const rMinute = cmb_Reserve_mm.getValue();

        // 현재시간
        const dateA = new Date(pYear, pMonth, pDay, pHour, pMinute);
        // 예약전송 시간
        const dateB = new Date(rYear, rMonth, rDay, rHour, rMinute);
        const mSecond = Math.floor(dateB.getTime() - dateA.getTime()) / 1000;
        const mMinute = Math.floor(mSecond / 60);
        const mHour = Math.floor(mMinute / 60);
        const mDay = Math.floor(mHour / 24);
        const diff_hour = Math.floor(mHour % 24);
        const diff_minute = Math.floor(mMinute % 60);

        // alert ('계산시간 : ' + mDay + '일 ' + diff_hour + ' 시간 ' + diff_minute + ' 분' );

        if (mDay > 0 || diff_hour > 0 || diff_minute >= 10) {
            return true;
        } else {
            await $c.win.alert("예약메시지 전송은 현재시간을 기준으로 10분 이후부터 가능합니다.");
            return false;
        }
    }
    if (cmb_EMAIL.getValue() === 'Y') {
        if (js_svrGubun === 'local' || js_svrGubun === 'dev' || js_svrGubun === 'test') {
            await $c.win.alert("◆ 주의 사항 ◆\n\n개발환경에서도 메일이 발송되므로 수신자 메일주소를 확인바랍니다.");
        }
    }
    return true;
};

/**
 * @method
 * @name cancel
 * @description cancel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cancel = async function() {
    await scwin.setHeader();
    scwin.setCode();
    fn_ReadBasicInfo();
};

/**
 * @method
 * @name selectAll
 * @description select All 처리
 * @returns {void}
 * @hidden N
 */
scwin.selectAll = function() {
    grd_Receiver.Redraw = false;
    if (scwin.gAllChk === false) {
        // 현재상태가 false이면 전체선택을 클릭릭한것

        scwin.gAllChk = true;
        dts_Receiver.setBroadcast(false);
        for (let i = 0; i < dts_Receiver.getRowCount(); i++) {
            dts_Receiver.setCellData(i + 1, "CHECK", "T");
        }
        dts_Receiver.setBroadcast(true, true);
        btn_SelectedAll.setValue("전체해제");
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        dts_Receiver.setBroadcast(false);
        for (let i = 0; i < dts_Receiver.getRowCount(); i++) {
            dts_Receiver.setCellData(i + 1, "CHECK", "F");
        }
        dts_Receiver.setBroadcast(true, true);
        btn_SelectedAll.setValue("전체선택");
    }
    grd_Receiver.Redraw = true;
};

/**
 * @method
 * @name rowCount
 * @description row Count 처리
 * @returns {void}
 * @hidden N
 */
scwin.rowCount = function() {
    // alert(dts_Receiver.CountRow);
    txb_totCnt.setValue("총건수 : " + dts_Receiver.getRowCount());
};

/**
 * @method
 * @name isNumber
 * @description is Number 처리
 * @param {*} inputVal inputVal
 * @returns {void}
 * @hidden N
 */
scwin.isNumber = function(inputVal) {
    oneDecimal = false;
    const inputStr = inputVal.toString();
    let oneChar;
    for (let i = 0; i < inputStr.length; i++) {
        oneChar = inputStr.charAt(i);
        if (i === 0 && oneChar === "-") {
            continue;
        }
        if (oneChar === "." && !oneDecimal) {
            oneDecimal = true;
            continue;
        }
        if (oneChar < "0" || oneChar > "9") {
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name setDataFromOpener
 * @description - 2022-07-26 by KHJ
 * @returns {void}
 * @hidden N
 */
scwin.setDataFromOpener = function() {
    if (frame.opener.dts_Target) {
        grd_Receiver.Redraw = false;
        const nRowCnt = frame.opener.dts_Target.getRowCount();
        // for문으로 데이터 넣으면 너무 느림.
        dts_Receiver.setJSON(frame.opener.dts_Target.ExportData(1, nRowCnt, false));
        txb_totCnt.setValue("총건수 : " + dts_Receiver.getRowCount());
        grd_Receiver.Redraw = true;
    }
};
